/**
 * Bundles Leaflet's JS and CSS into a TypeScript module so the in-app map works
 * without fetching the library from a CDN at runtime.
 *
 * Run after upgrading the `leaflet` dev dependency:
 *   node scripts/build-leaflet-assets.js
 */
const fs = require('fs');
const path = require('path');

const dist = path.join(__dirname, '..', 'node_modules', 'leaflet', 'dist');
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
// Marker / layer-control images are not used (the map draws its own HTML markers).
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8').replace(/url\([^)]*\)/g, 'none');

const out = `/* AUTO-GENERATED by scripts/build-leaflet-assets.js from leaflet ${
  require(path.join(dist, '..', 'package.json')).version
} (BSD-2-Clause). Do not edit. */
/* eslint-disable */
export const LEAFLET_JS: string = ${JSON.stringify(js)};
export const LEAFLET_CSS: string = ${JSON.stringify(css)};
`;

const target = path.join(__dirname, '..', 'src', 'components', 'map', 'leafletAssets.ts');
fs.writeFileSync(target, out, 'utf8');
console.log(`Wrote ${target} (${(out.length / 1024).toFixed(0)} KB)`);
